import{w as c,U as h}from"./index-C8KfyC2s.js";import{F as m}from"./index-CI7U31WA.js";import"./start-BrvnXvko.js";import"./chess-BJtO43a1.js";const g=[{id:"hoeren-a1-1",niveau:"A1",titel:"Hören: Im Café und Restaurant",szenen:[{setup:"Ein Gast bestellt in einem Café.",zeilen:[{who:"a",fr:"Bonjour, madame. Vous désirez ?",de:"Guten Tag, gnädige Frau. Was möchten Sie?"},{who:"b",fr:"Un café et un croissant, s’il vous plaît.",de:"Einen Kaffee und ein Croissant, bitte."},{who:"a",fr:"Très bien. Et avec ça ?",de:"Sehr gut. Und dazu?"},{who:"b",fr:"Un verre d’eau, s’il vous plaît.",de:"Ein Glas Wasser, bitte."}],ask:"Was isst die Frau?",opts:["Ein Croissant","Ein Schinkensandwich","Ein Stück Apfelkuchen","Einen Salat mit Brot"],why:"Sie bestellt „un café et un croissant“ und dazu ein Glas Wasser."},{setup:"Ein Gast möchte im Café bezahlen.",zeilen:[{who:"b",fr:"Monsieur, l’addition, s’il vous plaît.",de:"Mein Herr, die Rechnung, bitte."},{who:"a",fr:"Oui. Ça fait douze euros cinquante.",de:"Ja. Das macht zwölf Euro fünfzig."},{who:"b",fr:"Voilà. Merci beaucoup !",de:"Bitte sehr. Vielen Dank!"}],ask:"Wie viel kostet es?",opts:["12,50 €","2,50 €","12,15 €","15,12 €"],why:"„Douze euros cinquante“ heißt 12 Euro und 50 Cent."},{setup:"Drei Freunde kommen in ein Restaurant.",zeilen:[{who:"b",fr:"Bonjour. Une table pour trois, s’il vous plaît.",de:"Guten Tag. Einen Tisch für drei, bitte."},{who:"a",fr:"Oui. Près de la fenêtre ?",de:"Ja. Am Fenster?"},{who:"b",fr:"Oui, très bien. Merci.",de:"Ja, sehr gut. Danke."}],ask:"Wo möchten die Gäste sitzen?",opts:["Am Fenster","Auf der Terrasse","Hinten im Saal neben der Tür","Draußen an der Straße"],why:"Der Kellner fragt „Près de la fenêtre ?“, und der Gast antwortet „Oui, très bien“."}]},{id:"hoeren-a1-2",niveau:"A1",titel:"Hören: Sich vorstellen und den Weg fragen",szenen:[{setup:"Zwei Leute lernen sich auf einer Party kennen.",zeilen:[{who:"a",fr:"Bonjour, je m’appelle Marie. Et vous ?",de:"Guten Tag, ich heiße Marie. Und Sie?"},{who:"b",fr:"Je m’appelle Karim. Je suis de Lyon.",de:"Ich heiße Karim. Ich komme aus Lyon."},{who:"a",fr:"Vous habitez à Lyon ?",de:"Wohnen Sie in Lyon?"},{who:"b",fr:"Non, j’habite à Nantes maintenant.",de:"Nein, ich wohne jetzt in Nantes."}],ask:"Wo wohnt Karim jetzt?",opts:["In Nantes","In Lyon, wo er herkommt","In Paris","In einem Dorf bei Bordeaux"],why:"Er kommt aus Lyon („je suis de Lyon“), wohnt aber jetzt in Nantes („j’habite à Nantes maintenant“)."},{setup:"Zwei Bekannte sprechen über die Arbeit.",zeilen:[{who:"a",fr:"Qu’est-ce que tu fais dans la vie ?",de:"Was machst du beruflich?"},{who:"b",fr:"Je suis professeure d’allemand dans un lycée.",de:"Ich bin Deutschlehrerin an einem Gymnasium."},{who:"a",fr:"Tu aimes ton travail ?",de:"Gefällt dir deine Arbeit?"},{who:"b",fr:"Oui, beaucoup.",de:"Ja, sehr."}],ask:"Welches Fach unterrichtet die Frau?",opts:["Deutsch","Englisch","Spanisch","Mathematik"],why:"„Professeure d’allemand“ — Lehrerin für Deutsch."},{setup:"Eine Frau fragt auf der Straße nach dem Weg.",zeilen:[{who:"a",fr:"Excusez-moi, où est la gare, s’il vous plaît ?",de:"Entschuldigung, wo ist der Bahnhof, bitte?"},{who:"b",fr:"Allez tout droit, puis tournez à gauche.",de:"Gehen Sie geradeaus, dann biegen Sie links ab."},{who:"b",fr:"La gare est à côté de la banque.",de:"Der Bahnhof ist neben der Bank."},{who:"a",fr:"Merci beaucoup !",de:"Vielen Dank!"}],ask:"Wo liegt der Bahnhof?",opts:["Links, neben der Bank","Rechts, neben der Post","Geradeaus, vor der Kirche","Gleich hier hinter dem Markt"],why:"„Tournez à gauche“ und „à côté de la banque“ — links und neben der Bank."}]},{id:"hoeren-a1-3",niveau:"A1",titel:"Hören: Einkaufen, Uhrzeit und Öffnungszeiten",szenen:[{setup:"Eine Kundin kauft auf dem Markt ein.",zeilen:[{who:"a",fr:"Bonjour ! Je voudrais deux kilos de pommes.",de:"Guten Tag! Ich möchte zwei Kilo Äpfel."},{who:"b",fr:"Voilà. Et avec ça ?",de:"Bitte schön. Und dazu?"},{who:"a",fr:"Une baguette, s’il vous plaît.",de:"Ein Baguette, bitte."},{who:"b",fr:"Voilà. Ça fait cinq euros.",de:"Bitte. Das macht fünf Euro."}],ask:"Wie viele Kilo Äpfel kauft die Kundin?",opts:["Zwei Kilo","Ein Kilo","Drei Kilo","Zwölf Kilo"],why:"„Deux kilos de pommes“ — zwei Kilo Äpfel."},{setup:"Zwei Freunde verabreden sich fürs Kino.",zeilen:[{who:"a",fr:"Le film commence à quelle heure ?",de:"Um wie viel Uhr beginnt der Film?"},{who:"b",fr:"À vingt heures quinze.",de:"Um zwanzig Uhr fünfzehn."},{who:"a",fr:"Et il finit à quelle heure ?",de:"Und wann endet er?"},{who:"b",fr:"À vingt-deux heures.",de:"Um zweiundzwanzig Uhr."}],ask:"Wann beginnt der Film?",opts:["Um 20:15 Uhr","Um 20:50 Uhr","Um 18:15 Uhr","Um 22:00 Uhr"],why:"„À vingt heures quinze“ — 20:15 Uhr; um 22 Uhr (vingt-deux heures) ist er zu Ende."},{setup:"Eine Ansage am Telefon einer Apotheke.",zeilen:[{who:"n",fr:"Bonjour. La pharmacie est ouverte du lundi au samedi.",de:"Guten Tag. Die Apotheke ist von Montag bis Samstag geöffnet."},{who:"n",fr:"Elle ouvre à neuf heures et ferme à dix-neuf heures.",de:"Sie öffnet um neun Uhr und schließt um neunzehn Uhr."},{who:"n",fr:"Le dimanche, elle est fermée. Merci !",de:"Am Sonntag ist sie geschlossen. Danke!"}],ask:"Wann hat die Apotheke am Sonntag geöffnet?",opts:["Gar nicht, sie ist geschlossen","Von neun bis neunzehn Uhr","Nur am Vormittag","Von zehn bis sechzehn Uhr"],why:"„Le dimanche, elle est fermée“ — sonntags ist sie geschlossen."}]},{id:"hoeren-a2-1",niveau:"A2",titel:"Hören: Reisen und Unterkunft",szenen:[{setup:"Eine Frau kommt in einem Hotel an.",zeilen:[{who:"a",fr:"Bonjour, j’ai réservé une chambre au nom de Martin.",de:"Guten Tag, ich habe ein Zimmer auf den Namen Martin reserviert."},{who:"b",fr:"Oui, une chambre pour deux nuits. Voici votre clé.",de:"Ja, ein Zimmer für zwei Nächte. Hier ist Ihr Schlüssel."},{who:"a",fr:"Le petit-déjeuner est compris ?",de:"Ist das Frühstück inklusive?"},{who:"b",fr:"Oui, de sept heures à dix heures, au rez-de-chaussée.",de:"Ja, von sieben bis zehn Uhr, im Erdgeschoss."}],ask:"Bis wann gibt es Frühstück?",opts:["Bis zehn Uhr","Bis elf Uhr","Bis neun Uhr","Nur bis halb acht"],why:"„De sept heures à dix heures“ — von sieben bis zehn Uhr."},{setup:"Durchsage im Bahnhof.",zeilen:[{who:"n",fr:"Attention, mesdames et messieurs. Le train pour Lyon a vingt minutes de retard.",de:"Achtung, meine Damen und Herren. Der Zug nach Lyon hat zwanzig Minuten Verspätung."},{who:"n",fr:"Départ prévu à quatorze heures trente.",de:"Geplante Abfahrt um vierzehn Uhr dreißig."},{who:"n",fr:"Il va partir de la voie quatre. Excusez-nous pour ce retard.",de:"Er wird von Gleis vier abfahren. Wir bitten um Entschuldigung für die Verspätung."}],ask:"Wie viel Verspätung hat der Zug?",opts:["Zwanzig Minuten","Zwölf Minuten","Vierzig Minuten","Eine halbe Stunde"],why:"„Vingt minutes de retard“ — zwanzig Minuten Verspätung; „quatorze heures trente“ ist nur die geplante Abfahrtszeit."},{setup:"Ein Reisender kauft am Schalter eine Fahrkarte.",zeilen:[{who:"a",fr:"Bonjour, un aller-retour pour Bordeaux, s’il vous plaît.",de:"Guten Tag, eine Hin- und Rückfahrkarte nach Bordeaux, bitte."},{who:"b",fr:"Pour quand ?",de:"Für wann?"},{who:"a",fr:"Pour demain. Je pars le matin et je reviens dimanche.",de:"Für morgen. Ich fahre morgens und komme am Sonntag zurück."},{who:"b",fr:"Très bien. Ça fait quarante-huit euros.",de:"Sehr gut. Das macht achtundvierzig Euro."}],ask:"Wann fährt der Reisende zurück?",opts:["Am Sonntag","Am Samstag","Schon morgen früh","Am Montag"],why:"„Je reviens dimanche“ — er kommt am Sonntag zurück; „demain“ ist nur die Hinfahrt."}]},{id:"hoeren-a2-2",niveau:"A2",titel:"Hören: Vergangenheit und Pläne",szenen:[{setup:"Zwei Kolleginnen sprechen am Montag über das Wochenende.",zeilen:[{who:"a",fr:"Alors, tu as passé un bon week-end ?",de:"Und, hattest du ein schönes Wochenende?"},{who:"b",fr:"Oui ! Samedi, je suis allée au marché avec ma sœur.",de:"Ja! Am Samstag war ich mit meiner Schwester auf dem Markt."},{who:"b",fr:"Et dimanche, nous avons mangé chez nos parents.",de:"Und am Sonntag haben wir bei unseren Eltern gegessen."},{who:"a",fr:"Super. Et tu as vu Paul ?",de:"Toll. Und hast du Paul gesehen?"},{who:"b",fr:"Non, il a travaillé tout le week-end.",de:"Nein, er hat das ganze Wochenende gearbeitet."}],ask:"Was hat die Frau am Samstag gemacht?",opts:["Sie war mit ihrer Schwester auf dem Markt","Sie hat bei den Eltern gegessen","Sie hat Paul getroffen","Sie hat den ganzen Tag gearbeitet"],why:"„Samedi, je suis allée au marché avec ma sœur“; Eltern waren am Sonntag, und gearbeitet hat Paul."},{setup:"Zwei Nachbarn sprechen über den Sommer.",zeilen:[{who:"a",fr:"Qu’est-ce que vous allez faire cet été ?",de:"Was werdet ihr diesen Sommer machen?"},{who:"b",fr:"Nous allons partir en Bretagne, en voiture.",de:"Wir fahren in die Bretagne, mit dem Auto."},{who:"a",fr:"Pour combien de temps ?",de:"Für wie lange?"},{who:"b",fr:"Pour deux semaines. On va dormir dans un petit camping.",de:"Für zwei Wochen. Wir werden auf einem kleinen Campingplatz schlafen."}],ask:"Wie lange dauert die Reise?",opts:["Zwei Wochen","Drei Wochen","Zwei Tage","Einen ganzen Monat"],why:"„Pour deux semaines“ — für zwei Wochen."},{setup:"Eine Mutter und ihr Sohn sprechen am Morgen.",zeilen:[{who:"a",fr:"Tu es rentré tard hier soir ?",de:"Bist du gestern Abend spät nach Hause gekommen?"},{who:"b",fr:"Oui, à minuit. Nous avons regardé un film chez Karim.",de:"Ja, um Mitternacht. Wir haben bei Karim einen Film geschaut."},{who:"a",fr:"Et ce soir ?",de:"Und heute Abend?"},{who:"b",fr:"Ce soir, je vais rester à la maison. Je suis fatigué.",de:"Heute Abend bleibe ich zu Hause. Ich bin müde."}],ask:"Was macht der Sohn heute Abend?",opts:["Er bleibt zu Hause","Er geht wieder zu Karim","Er schaut einen Film im Kino","Er kommt erst um Mitternacht heim"],why:"„Je vais rester à la maison“ — der Film bei Karim war gestern Abend."}]},{id:"hoeren-a2-3",niveau:"A2",titel:"Hören: Gesundheit, Arbeit und Telefon",szenen:[{setup:"Ein Mann ruft in einer Arztpraxis an.",zeilen:[{who:"a",fr:"Cabinet du docteur Roux, bonjour.",de:"Praxis Doktor Roux, guten Tag."},{who:"b",fr:"Bonjour, je voudrais un rendez-vous. J’ai mal à la gorge depuis hier.",de:"Guten Tag, ich möchte einen Termin. Ich habe seit gestern Halsschmerzen."},{who:"a",fr:"Je peux vous proposer jeudi à quatorze heures quinze.",de:"Ich kann Ihnen Donnerstag um vierzehn Uhr fünfzehn anbieten."},{who:"b",fr:"Jeudi, c’est parfait. Merci.",de:"Donnerstag ist perfekt. Danke."}],ask:"Wann ist der Arzttermin?",opts:["Donnerstag um 14:15 Uhr","Donnerstag um 14:50 Uhr","Dienstag um 14:15 Uhr","Donnerstag um 15:15 Uhr"],why:"„Jeudi à quatorze heures quinze“ — Donnerstag, 14:15 Uhr."},{setup:"Eine Nachricht auf dem Anrufbeantworter.",zeilen:[{who:"n",fr:"Bonjour, c’est Sophie. Je suis désolée.",de:"Guten Tag, hier ist Sophie. Es tut mir leid."},{who:"n",fr:"Je ne peux pas venir à la réunion demain.",de:"Ich kann morgen nicht zur Besprechung kommen."},{who:"n",fr:"J’ai un rendez-vous chez le dentiste à dix heures.",de:"Ich habe um zehn Uhr einen Termin beim Zahnarzt."},{who:"n",fr:"Rappelle-moi ce soir, s’il te plaît. À bientôt !",de:"Ruf mich heute Abend zurück, bitte. Bis bald!"}],ask:"Warum kann Sophie nicht zur Besprechung kommen?",opts:["Sie hat einen Zahnarzttermin","Sie ist krank","Ihr Zug hat Verspätung","Sie muss ihr Kind abholen"],why:"„J’ai un rendez-vous chez le dentiste“ — sie hat einen Termin beim Zahnarzt."},{setup:"Zwei Freunde telefonieren wegen ihrer Verabredung.",zeilen:[{who:"a",fr:"Allô, Julie ? C’est Paul. Pour demain, c’est toujours d’accord ?",de:"Hallo, Julie? Hier ist Paul. Bleibt es morgen dabei?"},{who:"b",fr:"Justement, j’ai un problème. Je travaille jusqu’à sept heures.",de:"Gerade deshalb, ich habe ein Problem. Ich arbeite bis sieben Uhr."},{who:"a",fr:"Pas de problème. On peut se voir à huit heures, devant le cinéma ?",de:"Kein Problem. Können wir uns um acht Uhr vor dem Kino treffen?"},{who:"b",fr:"Oui, d’accord. À demain !",de:"Ja, einverstanden. Bis morgen!"}],ask:"Wann und wo treffen sie sich?",opts:["Um acht Uhr vor dem Kino","Um sieben Uhr vor dem Kino","Um acht Uhr in einem Café","Um halb acht am Bahnhof"],why:"„À huit heures, devant le cinéma“ — um acht Uhr vor dem Kino; bis sieben arbeitet Julie."}]}],p=[{id:"hoeren-b1-1",niveau:"B1",titel:"Hören: Meinungen und Diskussion",szenen:[{setup:"Zwei Kolleginnen sprechen über Arbeiten von zu Hause.",zeilen:[{who:"a",fr:"Moi, je préfère travailler à la maison. Je gagne presque deux heures par jour, parce que je n'ai plus de transports.",de:"Ich arbeite lieber zu Hause. Ich gewinne fast zwei Stunden am Tag, weil ich nicht mehr pendeln muss."},{who:"b",fr:"Pas moi. Chez moi, je n'arrive pas à me concentrer, et puis les collègues me manquent.",de:"Ich nicht. Zu Hause kann ich mich nicht konzentrieren, und außerdem fehlen mir die Kollegen."},{who:"a",fr:"Du coup, tu y vas tous les jours ?",de:"Gehst du also jeden Tag ins Büro?"},{who:"b",fr:"Oui, sauf le vendredi. Ce jour-là, je reste chez moi.",de:"Ja, außer freitags. An dem Tag bleibe ich zu Hause."}],ask:"Warum arbeitet die erste Person lieber zu Hause?",opts:["Sie spart Zeit, weil sie nicht mehr pendeln muss","Sie kann sich dort besser konzentrieren","Ihr Chef verlangt es","Sie vermeidet ihre Kollegen"],why:"Die erste Person sagt: „Je gagne presque deux heures par jour, parce que je n’ai plus de transports.“ (Konzentration und Kollegen nennt die andere Person.)"},{setup:"Zwei Freunde überlegen, ob man lieber in der Stadt oder auf dem Land lebt.",zeilen:[{who:"a",fr:"Je voudrais déménager à la campagne. Ici, il y a trop de bruit et tout est cher.",de:"Ich möchte aufs Land ziehen. Hier ist es zu laut, und alles ist teuer."},{who:"b",fr:"Moi, je ne pourrais pas. Sans voiture, on ne peut rien faire là-bas, et il n'y a presque pas de commerces.",de:"Ich könnte das nicht. Ohne Auto kann man dort nichts machen, und es gibt fast keine Geschäfte."},{who:"a",fr:"Mais on a plus de calme, et on respire mieux !",de:"Aber man hat mehr Ruhe, und man atmet besser!"},{who:"b",fr:"Peut-être, mais le calme ne remplace pas un cinéma à côté de chez soi.",de:"Vielleicht, aber Ruhe ersetzt kein Kino in der Nähe."}],ask:"Warum möchte die erste Person aufs Land ziehen?",opts:["Weil es in der Stadt zu laut und zu teuer ist","Weil sie dort ein Auto braucht","Weil dort ein Kino in der Nähe ist","Weil ihre Familie dort wohnt"],why:"Sie sagt: „Ici, il y a trop de bruit et tout est cher.“ — in der Stadt ist es zu laut und zu teuer."},{setup:"Zwei Eltern sprechen über Handys in der Schule.",zeilen:[{who:"a",fr:"Je trouve qu'on devrait interdire le portable au collège. Les élèves ne se parlent plus pendant la pause.",de:"Ich finde, man sollte das Handy in der Schule verbieten. Die Schüler reden in der Pause nicht mehr miteinander."},{who:"b",fr:"Je ne suis pas tout à fait d'accord. Mon fils s'en sert pour chercher des mots, et s'il y a un problème, il peut m'appeler.",de:"Da stimme ich nicht ganz zu. Mein Sohn benutzt es, um Wörter nachzuschlagen, und bei einem Problem kann er mich anrufen."},{who:"a",fr:"Alors il faudrait au moins l'interdire pendant les cours.",de:"Dann sollte man es wenigstens im Unterricht verbieten."},{who:"b",fr:"Ça, oui, je suis d'accord.",de:"Dem stimme ich zu."}],ask:"Worauf einigen sich die beiden am Ende?",opts:["Im Unterricht soll das Handy verboten sein","Das Handy soll in der Schule ganz verboten werden","Das Handy soll nur in der Pause verboten sein","Das Handy soll überall erlaubt bleiben"],why:"Die erste Person schlägt vor: „au moins l’interdire pendant les cours“, und die zweite antwortet: „Ça, oui, je suis d’accord.“"}]},{id:"hoeren-b1-2",niveau:"B1",titel:"Hören: Berichte und Nachrichten",szenen:[{setup:"Eine Verkehrsmeldung im Radio.",zeilen:[{who:"n",fr:"Voici les informations routières. Sur l'autoroute du Sud, un accident a eu lieu ce matin près de la sortie de Valmont.",de:"Hier die Verkehrsmeldungen. Auf der Südautobahn hat sich heute Morgen in der Nähe der Ausfahrt Valmont ein Unfall ereignet."},{who:"n",fr:"Il y a six kilomètres de bouchons en direction de la ville. Nous vous conseillons de prendre la route départementale.",de:"Es gibt sechs Kilometer Stau in Richtung Stadt. Wir empfehlen Ihnen, die Landstraße zu nehmen."}],ask:"Was rät der Sprecher den Autofahrern?",opts:["Die Landstraße zu nehmen","Zu Hause zu bleiben","Eine Stunde zu warten","Lieber mit dem Zug zu fahren"],why:"„Nous vous conseillons de prendre la route départementale.“ — er empfiehlt die Landstraße."},{setup:"Der Wetterbericht für morgen im Radio.",zeilen:[{who:"n",fr:"Météo de demain : le matin, du brouillard dans tout l'ouest, puis le soleil reviendra vers midi.",de:"Das Wetter für morgen: Am Morgen Nebel im ganzen Westen, dann kommt gegen Mittag die Sonne zurück."},{who:"n",fr:"L'après-midi, un orage est possible dans les montagnes.",de:"Am Nachmittag ist in den Bergen ein Gewitter möglich."},{who:"n",fr:"Si vous partez en randonnée, prenez un vêtement de pluie, et faites attention au vent le soir.",de:"Wenn Sie wandern gehen, nehmen Sie Regenkleidung mit und achten Sie abends auf den Wind."}],ask:"Was ist am Nachmittag in den Bergen möglich?",opts:["Ein Gewitter","Nebel","Dauerhaft strahlender Sonnenschein","Starker Frost"],why:"„L’après-midi, un orage est possible dans les montagnes.“ (Nebel gilt für den Morgen.)"},{setup:"Zwei Freunde sprechen über einen Veranstaltungshinweis, den sie im Radio gehört haben.",zeilen:[{who:"a",fr:"Tu as entendu la radio ? Il y a un marché de Noël ce week-end, sur la place de la Mairie.",de:"Hast du das Radio gehört? Dieses Wochenende gibt es einen Weihnachtsmarkt auf dem Rathausplatz."},{who:"b",fr:"Oui, il ouvre samedi à dix heures. L'entrée est gratuite, mais il faut réserver pour la patinoire.",de:"Ja, er öffnet am Samstag um zehn Uhr. Der Eintritt ist frei, aber für die Eisbahn muss man reservieren."},{who:"a",fr:"On y va samedi après-midi ?",de:"Gehen wir Samstagnachmittag hin?"},{who:"b",fr:"Plutôt dimanche. Samedi, j'ai promis d'aider ma sœur à déménager.",de:"Lieber Sonntag. Am Samstag habe ich versprochen, meiner Schwester beim Umzug zu helfen."}],ask:"Warum gehen die beiden nicht am Samstag hin?",opts:["Die zweite Person hilft ihrer Schwester beim Umzug","Der Markt öffnet erst am Sonntag","Die Eisbahn ist samstags ausgebucht","Der Eintritt kostet samstags Geld"],why:"„Samedi, j’ai promis d’aider ma sœur à déménager.“ — der Markt öffnet schon samstags und der Eintritt ist frei."}]},{id:"hoeren-b1-3",niveau:"B1",titel:"Hören: Erzählen und Pläne",szenen:[{setup:"Zwei Freunde: Einer erzählt, was ihm gestern passiert ist.",zeilen:[{who:"a",fr:"Qu'est-ce qui t'est arrivé hier ? Tu as l'air fatigué.",de:"Was ist dir gestern passiert? Du siehst müde aus."},{who:"b",fr:"Je suis arrivé à la gare, mais mon train était déjà parti. Je n'avais pas vu que l'horaire avait changé.",de:"Ich bin am Bahnhof angekommen, aber mein Zug war schon weg. Ich hatte nicht gesehen, dass sich der Fahrplan geändert hatte."},{who:"a",fr:"Et alors ?",de:"Und dann?"},{who:"b",fr:"J'ai attendu une heure. Il pleuvait, et je n'avais pas de parapluie, parce que le prochain train partait à neuf heures.",de:"Ich habe eine Stunde gewartet. Es regnete, und ich hatte keinen Schirm, denn der nächste Zug fuhr um neun Uhr."}],ask:"Warum hat er seinen Zug verpasst?",opts:["Er hatte nicht bemerkt, dass sich der Fahrplan geändert hatte","Er ist zu spät aufgestanden","Der Zug ist ausgefallen","Er hat den falschen Bahnsteig genommen"],why:"„Je n’avais pas vu que l’horaire avait changé.“ — er hatte die Fahrplanänderung nicht gesehen."},{setup:"Zwei Freunde träumen davon, was sie tun würden, wenn alles möglich wäre.",zeilen:[{who:"a",fr:"Si j'avais plus d'argent, je voyagerais au Canada pendant un an.",de:"Wenn ich mehr Geld hätte, würde ich ein Jahr lang nach Kanada reisen."},{who:"b",fr:"Moi, si je gagnais à la loterie, j'achèterais d'abord une petite maison au bord de la mer.",de:"Wenn ich im Lotto gewänne, würde ich zuerst ein kleines Haus am Meer kaufen."},{who:"a",fr:"Et tu quitterais ton travail ?",de:"Und würdest du deine Arbeit kündigen?"},{who:"b",fr:"Non, pas du tout. Je réduirais seulement mes heures.",de:"Nein, überhaupt nicht. Ich würde nur meine Stunden reduzieren."}],ask:"Was würde die zweite Person bei einem Lottogewinn zuerst tun?",opts:["Ein kleines Haus am Meer kaufen","Ein Jahr lang nach Kanada reisen","Ihre Arbeit kündigen","Eine Weltreise planen"],why:"„Si je gagnais à la loterie, j’achèterais d’abord une petite maison au bord de la mer.“ — Kanada ist der Traum der ersten Person."},{setup:"Zwei Freunde: Einer hat bald eine wichtige Prüfung und bekommt Rat.",zeilen:[{who:"a",fr:"Je passe mon examen de conduite lundi, et j'ai très peur.",de:"Ich mache am Montag meine Fahrprüfung und habe große Angst."},{who:"b",fr:"Il faut que tu dormes bien dimanche soir. Et il faut que tu arrives en avance, pour que tu sois calme.",de:"Du musst am Sonntagabend gut schlafen. Und du musst früh dort sein, damit du ruhig bist."},{who:"a",fr:"Je devrais encore m'entraîner dimanche, non ?",de:"Ich sollte am Sonntag noch üben, oder?"},{who:"b",fr:"Non, il vaut mieux que tu te reposes.",de:"Nein, es ist besser, dass du dich ausruhst."}],ask:"Was rät die zweite Person für den Sonntag?",opts:["Sich ausruhen und nicht mehr üben","Noch einmal ausgiebig üben","Den Prüfungstermin verschieben","Mit einem Freund zusammen fahren"],why:"„Non, il vaut mieux que tu te reposes.“ — sie rät zum Ausruhen statt zum Üben."}]}],f=[{id:"hoeren-b2-1",niveau:"B2",titel:"Hören: Interview und Reportage",szenen:[{setup:"Ein Radiointerview mit einer Schlafforscherin (erfundene Person).",zeilen:[{who:"a",fr:"Bonjour à tous. Notre invitée, spécialiste du sommeil, va nous parler de nos nuits. Madame, que conseillez-vous en priorité ?",de:"Guten Tag allerseits. Unsere Gästin, eine Schlafexpertin, spricht über unsere Nächte. Was raten Sie vor allem?"},{who:"b",fr:"D'abord, se coucher à heures régulières. Ce qui compte, ce n'est pas tant la durée que la régularité.",de:"Zuerst: zu regelmäßigen Zeiten ins Bett gehen. Entscheidend ist nicht so sehr die Dauer als die Regelmäßigkeit."},{who:"a",fr:"Beaucoup de gens regardent leur téléphone au lit. Est-ce vraiment grave ?",de:"Viele Menschen schauen im Bett aufs Handy. Ist das wirklich schlimm?"},{who:"b",fr:"Pas systématiquement, mais la lumière des écrans retarde l'endormissement. Je recommande d'arrêter une demi-heure avant.",de:"Nicht unbedingt, aber das Licht der Bildschirme verzögert das Einschlafen. Ich empfehle, eine halbe Stunde vorher aufzuhören."},{who:"a",fr:"Et si l'on se réveille en pleine nuit ?",de:"Und wenn man mitten in der Nacht aufwacht?"},{who:"b",fr:"Surtout, il ne faut pas regarder l'heure. Cela crée du stress, et c'est ce stress qui empêche de se rendormir.",de:"Vor allem soll man nicht auf die Uhr schauen. Das erzeugt Stress, und dieser Stress verhindert das Wiedereinschlafen."}],ask:"Was hält die Expertin für wichtiger als die Schlafdauer?",opts:["Dass man zu regelmäßigen Zeiten ins Bett geht","Dass man mindestens acht Stunden schläft","Dass man nie ein Handy benutzt","Dass man nachts auf die Uhr schaut"],why:"Sie sagt: „Ce qui compte, ce n’est pas tant la durée que la régularité.“ (Das Handy sei „pas systématiquement“ schlimm; auf die Uhr zu schauen schade.)"},{setup:"Eine Reporterin spricht mit einem Forscher über den Weg zur Arbeit (erfundene Person).",zeilen:[{who:"a",fr:"Vous étudiez les trajets entre le domicile et le travail. Qu'est-ce qui vous a le plus surpris ?",de:"Sie untersuchen die Wege zwischen Wohnung und Arbeit. Was hat Sie am meisten überrascht?"},{who:"b",fr:"La durée du trajet n'est pas le plus important. Ce qui fatigue, c'est l'incertitude : on ne sait jamais si le train aura du retard.",de:"Die Dauer des Wegs ist nicht das Wichtigste. Was ermüdet, ist die Unsicherheit: Man weiß nie, ob der Zug Verspätung hat."},{who:"a",fr:"Donc un long trajet régulier serait moins pénible qu'un court trajet imprévisible ?",de:"Ein langer, gleichmäßiger Weg wäre also weniger lästig als ein kurzer, unberechenbarer?"},{who:"b",fr:"Exactement. Quelqu'un qui met toujours une heure se plaint moins que quelqu'un qui met vingt minutes, parfois quarante.",de:"Genau. Wer immer eine Stunde braucht, beklagt sich weniger als jemand, der zwanzig Minuten braucht, manchmal vierzig."},{who:"a",fr:"Que peut-on faire concrètement ?",de:"Was kann man konkret tun?"},{who:"b",fr:"Partir un peu plus tôt. Cette petite marge enlève beaucoup de stress, même si l'on n'en profite pas toujours.",de:"Etwas früher losgehen. Dieser kleine Puffer nimmt viel Stress, auch wenn man ihn nicht immer nutzt."}],ask:"Was ermüdet Pendler laut dem Forscher vor allem?",opts:["Die Ungewissheit, ob alles pünktlich läuft","Die lange Fahrzeit","Überfüllte Züge","Der Lärm unterwegs"],why:"Er sagt: „Ce qui fatigue, c’est l’incertitude : on ne sait jamais si le train aura du retard.“ — und: „La durée du trajet n’est pas le plus important.“"},{setup:"Ein Radiointerview: Lernen im höheren Alter (erfundene Expertin).",zeilen:[{who:"a",fr:"On entend souvent qu'il est trop tard pour apprendre une langue après soixante ans. Qu'en pensez-vous ?",de:"Man hört oft, nach sechzig sei es zu spät, eine Sprache zu lernen. Was meinen Sie?"},{who:"b",fr:"C'est faux. Le cerveau reste capable d'apprendre. Les seniors avancent plus lentement au début, mais ils retiennent bien ce qui a du sens pour eux.",de:"Das stimmt nicht. Das Gehirn bleibt lernfähig. Ältere kommen anfangs langsamer voran, behalten aber gut, was für sie Sinn hat."},{who:"a",fr:"Donc tout le monde peut y arriver ?",de:"Also kann es jeder schaffen?"},{who:"b",fr:"À condition de pratiquer régulièrement. Un peu chaque jour vaut mieux qu'une longue séance par semaine, quel que soit l'âge.",de:"Unter der Bedingung, regelmäßig zu üben. Jeden Tag ein wenig ist besser als eine lange Einheit pro Woche, egal in welchem Alter."},{who:"a",fr:"Et pour la prononciation ?",de:"Und bei der Aussprache?"},{who:"b",fr:"Là, il faut être honnête : l'accent est plus difficile à changer. Mais se faire comprendre reste largement possible.",de:"Da muss man ehrlich sein: Der Akzent ist schwerer zu verändern. Sich verständlich zu machen, bleibt aber weitgehend möglich."}],ask:"Was bleibt laut der Expertin im höheren Alter schwieriger?",opts:["Den Akzent zu verändern","Sich Wörter zu merken","Sich überhaupt verständlich zu machen","Mit einer Lerngruppe Schritt zu halten"],why:"Sie schränkt ein: „Là, il faut être honnête : l’accent est plus difficile à changer.“ (Wörter behalte man gut, und sich verständlich zu machen sei „largement possible“.)"}]},{id:"hoeren-b2-2",niveau:"B2",titel:"Hören: Argument und Gegenargument",szenen:[{setup:"Zwei Bekannte diskutieren über die Vier-Tage-Woche.",zeilen:[{who:"a",fr:"Je suis pour la semaine de quatre jours. On travaille mieux quand on est reposé, et les gens sont moins souvent malades.",de:"Ich bin für die Vier-Tage-Woche. Man arbeitet besser, wenn man ausgeruht ist, und die Leute sind seltener krank."},{who:"b",fr:"Je comprends l'idée, mais je ne suis pas convaincu. Dans mon magasin, il faut quelqu'un tous les jours, donc il faudrait embaucher.",de:"Ich verstehe die Idee, bin aber nicht überzeugt. In meinem Laden muss jeden Tag jemand da sein, man müsste also einstellen."},{who:"a",fr:"Embaucher coûte cher, certes. Mais une équipe motivée rapporte aussi.",de:"Einstellen kostet viel, gewiss. Aber ein motiviertes Team bringt auch etwas ein."},{who:"b",fr:"Peut-être, mais pour les petites entreprises, ce serait impossible à financer. Je serais plutôt pour un essai limité.",de:"Vielleicht, aber für kleine Firmen wäre das nicht zu finanzieren. Ich wäre eher für einen begrenzten Versuch."}],ask:"Wie steht die zweite Person zur Vier-Tage-Woche?",opts:["Skeptisch, sie würde höchstens einen begrenzten Versuch befürworten","Sie lehnt jede Änderung der Arbeitszeit strikt ab","Sie ist begeistert und will sie sofort einführen","Sie befürwortet sie nur für Büroberufe"],why:"Sie sagt: „Je ne suis pas convaincu“ und am Ende: „Je serais plutôt pour un essai limité.“"},{setup:"Zwei Freunde streiten über ein Handyverbot in Cafés.",zeilen:[{who:"a",fr:"Dans le café où je vais, une règle est affichée : pas de téléphone aux tables. Moi, je trouve ça excellent, les gens se parlent enfin.",de:"In dem Café, in das ich gehe, hängt eine Regel aus: keine Handys an den Tischen. Ich finde das ausgezeichnet, die Leute reden endlich miteinander."},{who:"b",fr:"Bof. C'est une question de liberté. Si je veux lire mes messages en buvant mon café, personne n'a à me l'interdire.",de:"Na ja. Das ist eine Frage der Freiheit. Wenn ich beim Kaffee meine Nachrichten lesen will, hat mir das niemand zu verbieten."},{who:"a",fr:"Mais le bruit des sonneries gêne les autres clients.",de:"Aber der Lärm der Klingeltöne stört die anderen Gäste."},{who:"b",fr:"Là, tu as raison : les sonneries, c'est pénible. Je veux bien qu'on demande de mettre le son en silencieux, mais pas d'interdire l'appareil.",de:"Da hast du recht: Klingeltöne nerven. Ich bin einverstanden, dass man bittet, den Ton auszuschalten, aber nicht das Gerät zu verbieten."}],ask:"Was gesteht die zweite Person zu?",opts:["Klingeltöne stören, man dürfe daher Stummschaltung verlangen","Das Handy solle im Café ganz verboten werden","Die Gäste redeten ohne Handy endlich mehr miteinander","Das Café dürfe Gäste mit Handy hinausschicken"],why:"Sie gibt nach: „Là, tu as raison : les sonneries, c’est pénible. Je veux bien qu’on demande de mettre le son en silencieux.“"},{setup:"Zwei Nachbarn reden über mehr Radwege in der Stadt.",zeilen:[{who:"a",fr:"Je voudrais que la ville construise plus de pistes cyclables. Moi, je laisse la voiture au garage depuis un an.",de:"Ich möchte, dass die Stadt mehr Radwege baut. Ich lasse das Auto seit einem Jahr in der Garage."},{who:"b",fr:"Je veux bien que le vélo se développe, mais j'habite loin, et avec mes enfants, la voiture est indispensable.",de:"Ich habe nichts dagegen, dass sich das Radfahren ausbreitet, aber ich wohne weit weg, und mit meinen Kindern ist das Auto unverzichtbar."},{who:"a",fr:"Je comprends. Pourtant, ce qui change tout, c'est la sécurité : les gens n'osent pas rouler, parce qu'ils ont peur des voitures.",de:"Ich verstehe das. Und doch ändert die Sicherheit alles: Die Leute trauen sich nicht zu fahren, weil sie Angst vor den Autos haben."},{who:"b",fr:"Ah, si le problème, c'est la peur, alors des pistes séparées de la route, je suis pour. Avec ça, j'essaierais peut-être.",de:"Ah, wenn das Problem die Angst ist, dann bin ich für Radwege, die von der Straße getrennt sind. Damit würde ich es vielleicht versuchen."}],ask:"Welches Argument überzeugt die zweite Person?",opts:["Von der Straße getrennte Radwege nähmen die Angst vor dem Autoverkehr","Dass die erste Person seit einem Jahr kein Auto mehr benutzt","Dass sie ohnehin nur wenige Kilometer vom Ziel entfernt wohnt","Dass das Radfahren viel Geld spart"],why:"Sie reagiert auf das Sicherheitsargument: „si le problème, c’est la peur, alors des pistes séparées de la route, je suis pour.“"}]},{id:"hoeren-b2-3",niveau:"B2",titel:"Hören: Vortrag, Ansage, Nachricht",szenen:[{setup:"Die Eröffnungsrede eines Abends in einem Stadtviertel.",zeilen:[{who:"n",fr:"Mesdames et messieurs, soyez les bienvenus à la première rencontre des jardins partagés de notre quartier. Nous sommes réunis ce soir dans l'ancienne école.",de:"Meine Damen und Herren, willkommen zum ersten Treffen der Gemeinschaftsgärten unseres Viertels. Wir sind heute Abend in der ehemaligen Schule versammelt."},{who:"n",fr:"Le but de cette soirée est simple : que les habitants fassent connaissance, pour que chacun puisse proposer un projet de jardin.",de:"Das Ziel dieses Abends ist einfach: dass die Bewohner sich kennenlernen, damit jeder ein Gartenprojekt vorschlagen kann."},{who:"n",fr:"Le buffet sera servi à vingt heures. Avant cela, trois associations présenteront leur travail dans la grande salle.",de:"Das Buffet wird um zwanzig Uhr serviert. Davor stellen drei Vereine in der großen Halle ihre Arbeit vor."}],ask:"Was ist das Ziel des Abends?",opts:["Die Bewohner lernen sich kennen und können Gartenprojekte vorschlagen","Geld für die ehemalige Schule zu sammeln","Drei neue Vereine zu gründen","Den Bewohnern fertige Gärten zu übergeben"],why:"Die Rednerin sagt: „que les habitants fassent connaissance, pour que chacun puisse proposer un projet de jardin.“ (Die drei Vereine stellen nur ihre Arbeit vor.)"},{setup:"Ein Programmhinweis im Fernsehen am Abend.",zeilen:[{who:"n",fr:"Et maintenant, notre programme de la soirée. À vingt et une heures, un documentaire sur la vie des abeilles, suivi d'un débat avec un apiculteur.",de:"Und nun unser Abendprogramm. Um einundzwanzig Uhr eine Dokumentation über das Leben der Bienen, danach eine Diskussion mit einem Imker."},{who:"n",fr:"Attention : en raison d'un match en direct, le film ne commencera pas à l'heure habituelle. Il sera diffusé une demi-heure plus tard que prévu.",de:"Achtung: Wegen eines Live-Spiels beginnt der Film nicht zur gewohnten Zeit. Er wird eine halbe Stunde später als geplant gesendet."},{who:"n",fr:"Le débat se terminera avant minuit, et le documentaire sera rediffusé dimanche matin.",de:"Die Diskussion endet vor Mitternacht, und die Dokumentation wird am Sonntagmorgen wiederholt."}],ask:"Wann beginnt die Dokumentation tatsächlich?",opts:["Um halb zehn abends, eine halbe Stunde später als geplant","Um neun Uhr abends","Um zehn Uhr abends","Um halb neun abends, weil das Programm vorgezogen wird"],why:"Geplant waren „vingt et une heures“, aber: „Il sera diffusé une demi-heure plus tard que prévu.“ — also halb zehn."},{setup:"Eine Radionachricht, danach sprechen zwei Kollegen darüber.",zeilen:[{who:"n",fr:"Selon une annonce de la mairie, le pont de la Rivière sera fermé pendant trois semaines à partir du mois prochain, car il doit être réparé.",de:"Laut einer Mitteilung der Stadtverwaltung wird die Flussbrücke ab nächstem Monat drei Wochen lang gesperrt, weil sie repariert werden muss."},{who:"n",fr:"Les voitures devront passer par le boulevard du Nord, tandis que les piétons et les cyclistes pourront utiliser une passerelle provisoire.",de:"Autos müssen über den Boulevard du Nord fahren, während Fußgänger und Radfahrer einen provisorischen Steg nutzen können."},{who:"a",fr:"Tu as entendu ? Le pont va fermer. Pour aller au travail, je vais devoir faire un grand détour.",de:"Hast du das gehört? Die Brücke wird gesperrt. Auf dem Weg zur Arbeit muss ich einen großen Umweg machen."},{who:"b",fr:"Pas forcément. Il y aura plus de bus pendant les travaux, paraît-il. Moi, je prendrai le vélo.",de:"Nicht unbedingt. Während der Arbeiten soll es mehr Busse geben. Ich nehme das Fahrrad."}],ask:"Was bedeutet die Sperrung für Autofahrer?",opts:["Sie müssen über den Boulevard du Nord ausweichen","Sie dürfen nur nachts über die Brücke fahren","Sie müssen den provisorischen Steg benutzen","Sie müssen eine Gebühr für die Umleitung zahlen"],why:"Die Nachricht: „Les voitures devront passer par le boulevard du Nord.“ (Der Steg gilt nur für Fußgänger und Radfahrer.)"}]}],b=[{id:"hoeren-c1-1",niveau:"C1",titel:"Hören: Vortrag und Fachgespräch",szenen:[{setup:"Eine Rednerin hält einen kurzen Vortrag über das gemeinsame Essen in der Familie (erfundene Person).",zeilen:[{who:"n",fr:"Permettez-moi de défendre une thèse modeste : le repas partagé compte moins par ce que l'on mange que par ce que l'on s'y dit.",de:"Erlauben Sie mir, eine bescheidene These zu vertreten: Die gemeinsame Mahlzeit zählt weniger durch das, was man isst, als durch das, was man dabei sagt."},{who:"n",fr:"Prenons une famille : lorsque la table est dressée, personne ne se précipite sur son téléphone, et les enfants racontent leur journée sans qu'on le leur demande.",de:"Nehmen wir eine Familie: Wenn der Tisch gedeckt ist, stürzt sich niemand aufs Telefon, und die Kinder erzählen von ihrem Tag, ohne dass man sie darum bittet."},{who:"n",fr:"Cela dit, il serait naïf de croire qu'un repas suffit à régler tous les conflits : certains soirs, la table devient plutôt le lieu des reproches.",de:"Allerdings wäre es naiv zu glauben, dass eine Mahlzeit alle Konflikte löst: An manchen Abenden wird der Tisch eher zum Ort der Vorwürfe."},{who:"n",fr:"Je conclurai donc ainsi : ce n'est pas l'assiette qui rapproche, c'est le temps que l'on accepte de lui consacrer.",de:"Ich schließe also so: Nicht der Teller bringt die Menschen näher, sondern die Zeit, die man bereit ist, ihm zu widmen."}],ask:"Welche These vertritt die Rednerin?",opts:["Am gemeinsamen Essen ist das Gespräch wichtiger als die Speisen","Gemeinsame Mahlzeiten lösen die Konflikte in einer Familie","Beim Essen sollte man vor allem auf gesunde Kost achten","Kinder sollten am Tisch erzählen dürfen, was sie wollen"],why:"Gleich zu Beginn: „le repas partagé compte moins par ce que l’on mange que par ce que l’on s’y dit.“ (Dass ein Essen alle Konflikte löse, nennt sie „naïf“.)"},{setup:"Eine Rednerin spricht über Museumsbesuche und erzählt dabei eine Begebenheit (erfundene Person).",zeilen:[{who:"n",fr:"Je voudrais vous parler de la manière dont nous visitons les musées. Trop souvent, on traverse dix salles pour n'en retenir aucune.",de:"Ich möchte über die Art sprechen, wie wir Museen besuchen. Allzu oft durchquert man zehn Säle und behält keinen davon."},{who:"n",fr:"Un exemple : un gardien m'a raconté qu'un visiteur était resté une heure devant un seul tableau, puis lui avait dit qu'il ne l'oublierait jamais.",de:"Ein Beispiel: Ein Aufseher erzählte mir, ein Besucher sei eine Stunde vor einem einzigen Gemälde geblieben und habe ihm danach gesagt, er werde es nie vergessen."},{who:"n",fr:"Je ne prétends pas qu'il faille toujours s'attarder ainsi ; certaines collections sont faites pour être parcourues vite, comme une promenade.",de:"Ich behaupte nicht, dass man immer so verweilen müsse; manche Sammlungen sind dafür gemacht, schnell durchschritten zu werden, wie bei einem Spaziergang."},{who:"n",fr:"Mon conseil est modeste : choisissez trois œuvres, pas une de plus, et laissez le reste pour une autre fois.",de:"Mein Rat ist bescheiden: Wählen Sie drei Werke, kein einziges mehr, und lassen Sie den Rest für ein andermal."}],ask:"Welches Beispiel führt die Rednerin an, um ihre Aussage zu stützen?",opts:["Ein Besucher blieb eine Stunde vor einem Bild und vergaß es nie","Ein Besucher durchquerte alle Säle in einer Stunde und war begeistert","Ein Aufseher bat einen Besucher, vom Gemälde zurückzutreten","Eine Führerin trieb ihre Gruppe zur Eile an"],why:"Sie erzählt: „un visiteur était resté une heure devant un seul tableau, puis lui avait dit qu’il ne l’oublierait jamais.“ (Die zehn Säle sind nur ihre Beschreibung des üblichen Fehlers.)"},{setup:"Eine Dozentin hält einen kurzen Vortrag über das Schreiben von Hand; ein Zuhörer fragt nach (erfundene Personen).",zeilen:[{who:"n",fr:"Écrire à la main ralentit, et c'est précisément pourquoi cela aide à mémoriser : on est obligé de choisir ce qui mérite d'être noté.",de:"Von Hand zu schreiben bremst, und genau deshalb hilft es beim Einprägen: Man muss auswählen, was es wert ist, notiert zu werden."},{who:"n",fr:"Je ne dis pas qu'il faille renoncer au clavier, dont la rapidité est précieuse lorsqu'on doit rédiger de longs textes.",de:"Ich sage nicht, dass man auf die Tastatur verzichten müsse, deren Schnelligkeit wertvoll ist, wenn man lange Texte verfassen muss."},{who:"a",fr:"Madame, si je vous comprends bien, vous déconseillez les ordinateurs en cours ?",de:"Wenn ich Sie richtig verstehe, raten Sie von Computern im Unterricht ab?"},{who:"n",fr:"Pas du tout. Je recommande seulement de réserver le stylo aux notes personnelles, et de garder le clavier pour les travaux à rendre.",de:"Keineswegs. Ich empfehle nur, den Stift für persönliche Notizen aufzuheben und die Tastatur für abzugebende Arbeiten zu behalten."}],ask:"Was antwortet die Dozentin auf die Nachfrage des Zuhörers?",opts:["Sie rät nicht vom Computer ab, sondern teilt Stift und Tastatur nach dem Zweck auf","Sie rät, Computer im Unterricht grundsätzlich zu verbieten","Sie empfiehlt, auch lange Texte stets mit der Hand zu schreiben","Sie hält die Handschrift nur für Kinder sinnvoll"],why:"Auf die Frage: „Pas du tout. Je recommande seulement de réserver le stylo aux notes personnelles, et de garder le clavier pour les travaux à rendre.“"}]},{id:"hoeren-c1-2",niveau:"C1",titel:"Hören: Debatte mit Nuancen",szenen:[{setup:"Zwei Bekannte sprechen über den Lärm in der Stadt, vor allem am Abend.",zeilen:[{who:"a",fr:"Ce qui m'épuise en ville, ce n'est pas la circulation, c'est le bruit des terrasses tard dans la soirée.",de:"Was mich in der Stadt erschöpft, ist nicht der Verkehr, sondern der Lärm der Terrassen spät am Abend."},{who:"b",fr:"Je vous l'accorde, c'est pénible. Pourtant, une ville où l'on n'entendrait plus personne serait-elle encore une ville ?",de:"Das gebe ich zu, es ist lästig. Und doch: Wäre eine Stadt, in der man niemanden mehr hört, noch eine Stadt?"},{who:"a",fr:"Je ne réclame pas le silence absolu. Je demande seulement que les terrasses ferment à une heure raisonnable.",de:"Ich verlange keine absolute Stille. Ich fordere nur, dass die Terrassen zu einer vernünftigen Stunde schließen."},{who:"b",fr:"Je veux bien en discuter, à condition que les cafetiers ne soient pas les seuls à en supporter le coût.",de:"Darüber lasse ich gern mit mir reden, vorausgesetzt, die Cafébetreiber tragen die Kosten nicht allein."},{who:"a",fr:"Que voulez-vous dire ?",de:"Was meinen Sie damit?"},{who:"b",fr:"Que la mairie les aide à isoler leurs salles, plutôt que de leur imposer une amende.",de:"Dass die Stadtverwaltung ihnen hilft, ihre Räume zu dämmen, statt ihnen ein Bußgeld aufzuerlegen."}],ask:"Welchen Vorbehalt macht die zweite Person?",opts:["Eine frühere Schließzeit sei denkbar, wenn die Cafébetreiber die Kosten nicht allein tragen","Sie stimmt nur zu, wenn die Terrassen dafür früher öffnen dürfen","Sie verlangt, dass nachts keine Autos mehr in die Stadt fahren","Sie lehnt jede Einschränkung ab, weil eine ruhige Stadt tot wäre"],why:"Sie sagt: „Je veux bien en discuter, à condition que les cafetiers ne soient pas les seuls à en supporter le coût.“"},{setup:"Zwei Freunde streiten freundlich über Lesen auf Papier oder auf dem Bildschirm.",zeilen:[{who:"a",fr:"Pour moi, un livre en papier, c'est le seul vrai plaisir de lecture. Rien ne le remplace.",de:"Für mich ist ein Buch aus Papier das einzige wahre Lesevergnügen. Nichts ersetzt es."},{who:"b",fr:"Bien sûr. Et pour partir en voyage, vous emportez toute votre bibliothèque dans la valise, c'est tellement pratique !",de:"Natürlich. Und für die Reise nehmen Sie Ihre ganze Bibliothek im Koffer mit, das ist ja so praktisch!"},{who:"a",fr:"Très drôle. Mais je n'emporte qu'un livre, et je le lis jusqu'au bout, ce que je ne fais jamais sur écran.",de:"Sehr witzig. Aber ich nehme nur ein Buch mit und lese es bis zum Ende, was ich am Bildschirm nie tue."},{who:"b",fr:"Là, je vous donne raison : sur écran, je survole plus que je ne lis.",de:"Da gebe ich Ihnen recht: Am Bildschirm überfliege ich mehr, als dass ich lese."}],ask:"Wie ist die Bemerkung der zweiten Person über die Bibliothek im Koffer gemeint?",opts:["Ironisch: Sie will zeigen, dass Papierbücher auf Reisen unpraktisch sind","Wörtlich: Sie lobt, wie praktisch viele Bücher im Koffer sind","Als Vorschlag, künftig mehr Bücher mitzunehmen","Als Kompliment für die große Sammlung der ersten Person"],why:"Das Wort „tellement pratique !“ steht im Gegensatz zum Bild einer ganzen Bibliothek im Koffer; die erste Person reagiert mit „Très drôle.“"},{setup:"Zwei Bekannte reden über ehrenamtliche Arbeit in Vereinen.",zeilen:[{who:"a",fr:"On croit que le bénévole donne de son temps. Moi, je crois qu'il reçoit plus qu'il ne donne : des amis, un rôle, le sentiment d'être utile.",de:"Man glaubt, der Freiwillige schenke seine Zeit. Ich glaube, er bekommt mehr, als er gibt: Freunde, eine Rolle, das Gefühl, nützlich zu sein."},{who:"b",fr:"Cela n'enlève rien au risque que certaines associations remplacent des emplois par des volontaires.",de:"Das ändert nichts an der Gefahr, dass manche Vereine Stellen durch Freiwillige ersetzen."},{who:"a",fr:"Le risque existe, je ne le nie pas, mais il ne change rien à mon propos : s'engager protège de l'isolement.",de:"Die Gefahr besteht, ich bestreite sie nicht, aber sie ändert nichts an meiner Aussage: Sich zu engagieren schützt vor Vereinsamung."},{who:"b",fr:"Soit, mais il faudra veiller à ce que cela reste un choix, et non une obligation déguisée.",de:"Meinetwegen, aber man muss darauf achten, dass es eine Entscheidung bleibt und keine verkappte Pflicht wird."}],ask:"Was ist das Kernargument der ersten Person?",opts:["Wer sich engagiert, bekommt viel zurück und ist weniger isoliert","Vereine sollten ihre Freiwilligen künftig besser bezahlen","Ehrenamtliche ersetzen sinnvollerweise bezahlte Stellen","Freiwillige helfen vor allem aus Pflichtgefühl"],why:"Sie sagt: „il reçoit plus qu’il ne donne“ und am Ende: „s’engager protège de l’isolement.“ (Die Sorge um ersetzte Stellen kommt von der zweiten Person.)"}]},{id:"hoeren-c1-3",niveau:"C1",titel:"Hören: Radio-Essay und Anekdote",szenen:[{setup:"Ein kurzer Radio-Essay über gute Vorsätze zum Jahresbeginn (erfundener Sprecher).",zeilen:[{who:"n",fr:"Chaque année, en janvier, nous prenons de bonnes résolutions avec le sérieux de ceux qui signent un traité de paix. Chaque année, février les enterre avec les honneurs.",de:"Jedes Jahr im Januar fassen wir gute Vorsätze mit dem Ernst derer, die einen Friedensvertrag unterzeichnen. Jedes Jahr beerdigt der Februar sie mit allen Ehren."},{who:"n",fr:"On se promet de courir, de lire, de ne plus manger de chocolat. On tient trois jours, quatre pour les plus vaillants.",de:"Man verspricht sich zu laufen, zu lesen, keine Schokolade mehr zu essen. Man hält drei Tage durch, vier die Tapfersten."},{who:"n",fr:"Je ne veux pas me moquer : il y a quelque chose de touchant dans cette obstination à vouloir changer de vie un premier janvier.",de:"Ich will mich nicht lustig machen: Es hat etwas Rührendes, an einem ersten Januar so hartnäckig sein Leben ändern zu wollen."},{who:"n",fr:"Peut-être la vraie sagesse consisterait-elle à prendre des résolutions modestes, que l'on pourrait tenir jusqu'à mars.",de:"Vielleicht bestünde die wahre Weisheit darin, bescheidene Vorsätze zu fassen, die man bis März durchhalten könnte."}],ask:"Welche Haltung nimmt der Sprecher gegenüber den guten Vorsätzen ein?",opts:["Leicht spöttisch, aber voller Zuneigung","Streng: Man sollte endlich disziplinierter sein","Verächtlich: Vorsätze seien völlig sinnlos","Begeistert: Er hält alle Vorsätze für erreichbar"],why:"Er scherzt über den Februar und die „trois jours“, sagt aber: „Je ne veux pas me moquer : il y a quelque chose de touchant dans cette obstination.“"},{setup:"Ein Radiosprecher erzählt eine kleine Anekdote über einen Nachbarn (erfundene Person).",zeilen:[{who:"n",fr:"Je voudrais vous raconter une petite histoire, que je tiens d'un voisin, homme sérieux, qui ne perd jamais rien.",de:"Ich möchte Ihnen eine kleine Geschichte erzählen, die ich von einem Nachbarn habe, einem ernsten Mann, der nie etwas verliert."},{who:"n",fr:"Un matin, il retourne tout l'appartement pour retrouver ses lunettes. Il fouille les tiroirs, soulève les coussins, interroge même le chat, qui reste muet.",de:"Eines Morgens stellt er die ganze Wohnung auf den Kopf, um seine Brille zu finden. Er durchwühlt die Schubladen, hebt die Kissen an, befragt sogar die Katze, die stumm bleibt."},{who:"n",fr:"Épuisé, il appelle sa sœur pour savoir si elle les a vues. Elle lui répond, après un silence : « Tu les as sur le nez. »",de:"Erschöpft ruft er seine Schwester an, um zu fragen, ob sie sie gesehen habe. Sie antwortet nach einem Schweigen: „Du hast sie auf der Nase.“"},{who:"n",fr:"Depuis ce jour, il ne dit plus qu'il ne perd jamais rien ; il dit seulement qu'il ne perd jamais rien d'important.",de:"Seit diesem Tag sagt er nicht mehr, er verliere nie etwas; er sagt nur noch, er verliere nie etwas Wichtiges."}],ask:"Worin besteht die Pointe der Anekdote?",opts:["Die gesuchte Brille hatte er die ganze Zeit auf der Nase","Die Schwester hatte die Brille versteckt","Die Brille lag in einer Schublade, die er zuerst übersehen hatte","Die Katze führte ihn schließlich zur Brille"],why:"Die Schwester sagt: „Tu les as sur le nez.“ (Schubladen und Katze gehören zur vergeblichen Suche.)"},{setup:"Ein kurzer Essay im Radio über Zweifel und Entschlossenheit; danach sprechen zwei Hörer darüber (erfundene Personen).",zeilen:[{who:"n",fr:"On reproche souvent aux indécis de ne jamais choisir. Je voudrais plaider pour eux : celui qui doute a au moins le mérite d'avoir écouté les autres.",de:"Man wirft den Unentschlossenen oft vor, nie zu wählen. Ich möchte für sie eintreten: Wer zweifelt, hat zumindest das Verdienst, den anderen zugehört zu haben."},{who:"n",fr:"Les gens sûrs d'eux se trompent avec aplomb, et on les applaudit. Les hésitants se trompent moins, mais en silence.",de:"Die Selbstsicheren irren sich mit Nachdruck, und man applaudiert ihnen. Die Zögernden irren sich weniger, aber lautlos."},{who:"n",fr:"J'en conclus qu'un doute bien placé vaut mieux qu'une certitude bruyante, sans pour autant faire de l'indécision une vertu.",de:"Ich schließe daraus, dass ein wohlplatzierter Zweifel mehr wert ist als eine laute Gewissheit, ohne aber die Unentschlossenheit zur Tugend zu machen."},{who:"a",fr:"Il est drôle, ce chroniqueur. Mais il ne plaide pas vraiment pour l'indécision, n'est-ce pas ?",de:"Der ist witzig, dieser Kolumnist. Aber er plädiert nicht wirklich für die Unentschlossenheit, oder?"},{who:"b",fr:"Non. Il garde le doute, qu'il juge utile, mais il refuse d'ériger l'hésitation en principe.",de:"Nein. Er behält den Zweifel, den er für nützlich hält, weigert sich aber, das Zögern zum Prinzip zu erheben."}],ask:"Welche Schlussfolgerung zieht der Sprecher des Essays?",opts:["Ein berechtigter Zweifel ist besser als laute Gewissheit, ohne dass Unentschlossenheit selbst eine Tugend wäre","Unentschlossenheit ist eine Tugend und verdient Förderung","Selbstsichere Menschen haben meistens recht","Man sollte besser nie eine Entscheidung treffen"],why:"Er schließt: „un doute bien placé vaut mieux qu’une certitude bruyante, sans pour autant faire de l’indécision une vertu.“"}]}],w=[...g,...p,...f,...b],l=n=>n.replace(/^fr-/,"");function z(n){const t=[...new Set(n.map(i=>i.region))],s=t.length,d=h.length;if(!s||!d)return;const a=t.map(()=>[]);h.forEach((i,e)=>{const r=Math.min(s-1,Math.floor(e*s/d)),o=String(i.nr).padStart(4,"0");a[r].push({id:`fr:satz-${o}`,kind:"vocab",variant:"vocab",title:`Sätze ${i.nr}`,region:t[r],data:{id:`satz-${o}`,topic:`Sätze ${i.nr}`,words:i.words}})});for(let i=s-1;i>=0;i--){if(!a[i].length)continue;const e=n.map(r=>r.region).lastIndexOf(t[i]);n.splice(e+1,0,...a[i])}}function v(){const n=m.flatMap(e=>e.knoten.map(r=>"vocab"in r?{id:`fr:${l(r.vocab.id??r.vocab.topic)}`,kind:"vocab",variant:"vocab",title:`Wortschatz — ${r.vocab.topic}`,region:e.region,data:r.vocab}:{id:`fr:${l(r.fact.id)}`,kind:"fact",variant:"fact",title:r.fact.title,region:e.region,data:r.fact}));z(n);for(const e of["A1","A2","B1","B2","C1"]){const r=w.filter(u=>u.niveau===e),o=n.map(u=>u.region.startsWith(e)).lastIndexOf(!0);!r.length||o<0||n.splice(o+1,0,...r.map(u=>({id:`fr:${u.id}`,kind:"listening",variant:"listening",title:u.titel,region:`${e} · Hören: Szenen aus dem Alltag`,data:u})))}const t=n.map(e=>e.region.startsWith("A1")).lastIndexOf(!0);if(t>=0){const e="A1-Abschlussprüfung — Französisch (DELF-Stil)";n.splice(t+1,0,{id:"EX:fr-a1",kind:"exam",variant:"exam",title:e,region:n[t].region,exam:{scope:"fr-a1",label:e}})}const s=n.map(e=>e.region.startsWith("A2")).lastIndexOf(!0);if(s>=0){const e="A2-Abschlussprüfung — Französisch (DELF-Stil)";n.splice(s+1,0,{id:"EX:fr-a2",kind:"exam",variant:"exam",title:e,region:n[s].region,exam:{scope:"fr-a2",label:e}})}const d=n.map(e=>e.region.startsWith("B1")).lastIndexOf(!0);if(d>=0){const e="B1-Abschlussprüfung — Französisch (DELF-Stil)";n.splice(d+1,0,{id:"EX:fr-b1",kind:"exam",variant:"exam",title:e,region:n[d].region,exam:{scope:"fr-b1",label:e}})}const a=n.map(e=>e.region.startsWith("B2")).lastIndexOf(!0);if(a>=0){const e="B2-Abschlussprüfung — Französisch (DELF-Stil)";n.splice(a+1,0,{id:"EX:fr-b2",kind:"exam",variant:"exam",title:e,region:n[a].region,exam:{scope:"fr-b2",label:e}})}const i=n.map(e=>e.region.startsWith("C1")).lastIndexOf(!0);if(i>=0){const e="C1-Abschlussprüfung — Französisch (DELF-Stil)";n.splice(i+1,0,{id:"EX:fr-c1",kind:"exam",variant:"exam",title:e,region:n[i].region,exam:{scope:"fr-c1",label:e}})}return c(n)}const A={main:v()};export{A as FR_PFADE};
